// Fruits and vegetables — concept glossary (Hebrew): a page per common fruit, vegetable, legume and nut, and per
// key term. For each: where it came from, how it reached Israel and the world, how it grows, its season in Israel,
// and the basics of what is in it. Origins and dates checked against two sources (2026-10-30); uncertain history
// is written cautiously ("כנראה", "לפי ההערכות"). No health promises, no brands or prices. Allergy and safety
// notes (peanuts, tree nuts, sesame, kiwi, fava/G6PD, bitter almonds, green potatoes, choking for small children).
const q = (question, right, wrong, exp) => ({ q: question, options: [right, ...wrong], exp })
// kind 'term' → "מה זה …?"; 'produce' → "… — עובדות לילדים". `foq` marks the "<X> פרי או ירק?" searches.
const concept = ({ kind = 'produce', foq = false, ...c }) => {
  const fallback = `${c.term} — המוצא, הדרך לישראל, איך גדלים, העונה בארץ ומה מיוחד. הסבר לילדים עם דוגמאות וחידון.`
  return {
    title: kind === 'term' ? `מה זה ${c.term}?` : foq ? `${c.term} — פרי או ירק? עובדות לילדים` : `${c.term} — עובדות לילדים`,
    seoTitle: kind === 'term' ? `מה זה ${c.term}? הסבר פשוט לילדים, דוגמאות וחידון`
      : foq ? `${c.term} — פרי או ירק? מוצא, גידול ועונה בישראל` : `${c.term} — מוצא, גידול ועונה בישראל: עובדות לילדים`,
    seoDesc: c.seoDesc || [`${c.short} עם חידון.`, c.short, fallback].find(s => s.length >= 70 && s.length <= 168) || fallback,
    ...c
  }
}

